const candidates = $input.all().map(i => i.json);
const total = candidates.length;
const stages = {
  applied: candidates.filter(c => c.stage === 'applied').length,
  screened: candidates.filter(c => c.stage === 'screened').length,
  interviewed: candidates.filter(c => c.stage === 'interviewed').length,
  offered: candidates.filter(c => c.stage === 'offered').length,
  hired: candidates.filter(c => c.stage === 'hired').length,
  rejected: candidates.filter(c => c.stage === 'rejected').length
};

const byPosition = {};
candidates.forEach(c => {
  if (!byPosition[c.position]) byPosition[c.position] = { total: 0, hired: 0 };
  byPosition[c.position].total++;
  if (c.stage === 'hired') byPosition[c.position].hired++;
});

const conversionRate = total > 0 ? ((stages.hired / total) * 100).toFixed(1) : 0;
const activeInPipeline = total - stages.hired - stages.rejected;

const positionSummary = Object.entries(byPosition).map(([pos, data]) => 
  `  • ${pos}: ${data.total} candidates (${data.hired} hired)`
).join('\n');

return [{ json: {
  total,
  stages,
  conversionRate,
  activeInPipeline,
  positionSummary,
  byPosition,
  date: new Date().toISOString().slice(0, 10)
}}];
